/**
 * UI Space — THE hierarchy source (slice 13).
 *
 * Every hierarchy citizen — the sunburst mesa and drum, the
 * treemap tray and cube, the data tree — and slice 12's
 * sub-node providers read ONE hierarchy from here: the
 * noctivagous-linux repository itself, snapshot-generated by
 * ui-space/tools/snapshot-repo.mjs into repo-snapshot.json
 * (directories are { name, children }, files are { name, value }
 * with value = size in bytes; directory values are sums,
 * computed by the consumers' own layout walks).
 *
 * Until this slice the citizens ate d3's FLARE placeholder.
 * The computing environment IS a hierarchy, so now they eat a
 * real one — this repo. (demo-de/src/sunburst-data.js remains
 * what it always was: the standalone sunburst page's dataset.
 * The space no longer imports it.)
 */

import snapshot from "./repo-snapshot.json" with { type: "json" };

/** The repository hierarchy: { name: "noctivagous-linux", children }. */
export const HIERARCHY = snapshot;

/** The hierarchy root's name — sub-node ids are name paths from it. */
export const HIERARCHY_ROOT_NAME = snapshot.name;
